sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float centerX;
uniform float centerY;
uniform float rayCount;
layout(color) uniform half4 tint;
half4 effectMain(float2 coord){half4 c=image.eval(coord);float2 p=coord/size-float2(centerX,centerY);float a=atan(p.y,p.x);float r=length(p);float rays=pow(abs(cos(a*rayCount*0.5+sin(r*12.0-(phase*0.0174532925)*0.4))),12.0);float fade=1.0-smoothstep(0.05,1.0,r);half3 add=tint.rgb*half(rays*fade*amount);return half4(clamp(c.rgb+add*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
